RAW = pathlib.Path.home() / ".cache" / "gobelin-images"
IMG = ROOT / "gobelin" / "img"
LOCK = os.path.join(os.environ.get("XDG_RUNTIME_DIR") or "/tmp", "parallax-gpu.lock")
RESERVE_MB = 3000
CHECKPOINT = "DreamShaperXL_Turbo_v2_1.safetensors"

NEGATIVE = ("text, letters, words, typography, writing, watermark, signature, logo, caption, "
            "label, ui, interface, photo of a real person, blurry, low quality, jpeg artifacts, "
            "extra limbs, deformed hands, nsfw, seamless pattern, tiling, wallpaper, yoda, star wars, "
            "bitcoin, dollar sign")

