def wait_for_memory():
    while True:
        with open("/proc/meminfo") as handle:
            free = next(int(l.split()[1]) // 1024 for l in handle if l.startswith("MemAvailable"))
        if free >= RESERVE_MB:
            return
        print(f"waiting: {free} MB free, {RESERVE_MB} wanted", flush=True)
        time.sleep(30)


# The open space is painted over this layout, so that the whiteboard sits where `ship` pastes its text.
BOARD = (70, 70, 830, 500)      # left, top, right, bottom, in the 1216x800 picture
BOARD_INSIDE = (84, 76, 830, 480)     # the painted board, measured on the seed that shipped


def layout():
    """A rough drawing of the room: a dark cellar, the board, a fridge, three screens, a desk."""
    from PIL import Image, ImageDraw, ImageFilter
    picture = Image.new("RGB", (1216, 800), (34, 32, 30))
    draw = ImageDraw.Draw(picture)
    draw.rectangle((0, 640, 1216, 800), fill=(66, 48, 32))
    draw.rectangle(BOARD, fill=(238, 240, 232), outline=(120, 120, 110), width=10)
    draw.rectangle((930, 110, 1130, 620), fill=(190, 192, 182))
    for x, colour in ((110, (170, 240, 70)), (480, (230, 90, 170)), (850, (100, 170, 240))):
        draw.rectangle((x, 530, x + 250, 660), fill=colour, outline=(10, 10, 10), width=8)
    path = RAW / "layout.png"
    RAW.mkdir(parents=True, exist_ok=True)
    picture.filter(ImageFilter.GaussianBlur(6)).save(path)
    return path


def upload(path):
    boundary = "gobelinimages"
    body = (f'--{boundary}\r\nContent-Disposition: form-data; name="image"; filename="{path.name}"\r\n'
            "Content-Type: image/png\r\n\r\n").encode() + path.read_bytes() + \
        f'\r\n--{boundary}\r\nContent-Disposition: form-data; name="overwrite"\r\n\r\ntrue\r\n--{boundary}--\r\n'.encode()
    request = urllib.request.Request(COMFY + "/upload/image", data=body,
                                     headers={"Content-Type": f"multipart/form-data; boundary={boundary}"})
    return json.load(urllib.request.urlopen(request))["name"]


def graph(prompt, seed, width, height, prefix, init=None):
    latent = {"class_type": "EmptyLatentImage",
              "inputs": {"width": width, "height": height, "batch_size": 1}}
    denoise = 1.0
    extra = {}
    if init:
        extra = {"8": {"class_type": "LoadImage", "inputs": {"image": init}}}
        latent = {"class_type": "VAEEncode", "inputs": {"pixels": ["8", 0], "vae": ["1", 2]}}
        denoise = 0.84
    return {**extra,
        "1": {"class_type": "CheckpointLoaderSimple", "inputs": {"ckpt_name": CHECKPOINT}},
        "2": {"class_type": "CLIPTextEncode", "inputs": {"text": prompt, "clip": ["1", 1]}},
        "3": {"class_type": "CLIPTextEncode", "inputs": {"text": NEGATIVE, "clip": ["1", 1]}},
        "4": latent,
        # 6, not 2, on this turbo model: under 3 the negative does not bite and lettering appears.
        "5": {"class_type": "KSampler",
              "inputs": {"seed": seed, "steps": 14, "cfg": 5.0, "sampler_name": "dpmpp_2m",
                         "scheduler": "karras", "denoise": denoise, "model": ["1", 0],
                         "positive": ["2", 0], "negative": ["3", 0], "latent_image": ["4", 0]}},
        "6": {"class_type": "VAEDecode", "inputs": {"samples": ["5", 0], "vae": ["1", 2]}},
        "7": {"class_type": "SaveImage", "inputs": {"filename_prefix": prefix, "images": ["6", 0]}},
    }


def generate(name, prompt, seed, width, height, out, init=None):
    target = out / f"{name}.png"
    wait_for_memory()
    start = time.time()
    with open(LOCK, "a+") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)    # waits for a parallax run, and blocks it while we paint
        body = json.dumps({"prompt": graph(prompt, seed, width, height, f"gobelin-{name}", init)}).encode()
        request = urllib.request.Request(COMFY + "/prompt", data=body,
                                         headers={"Content-Type": "application/json"})
        prompt_id = json.load(urllib.request.urlopen(request))["prompt_id"]
        while True:
            history = json.load(urllib.request.urlopen(f"{COMFY}/history/{prompt_id}"))
            if prompt_id in history:
                break
            time.sleep(1.5)
    images = [i for n in history[prompt_id].get("outputs", {}).values() for i in n.get("images", [])]
    if not images:
        raise RuntimeError(f"{name}: no image: {json.dumps(history[prompt_id].get('status'))[:400]}")
    query = urllib.parse.urlencode({"filename": images[0]["filename"],
                                    "subfolder": images[0].get("subfolder", ""), "type": "output"})
    out.mkdir(parents=True, exist_ok=True)
    target.write_bytes(urllib.request.urlopen(f"{COMFY}/view?{query}").read())
    print(f"{name}: seed {seed}, {time.time() - start:.0f} s -> {target}", flush=True)


def takes():
    for style, look in STYLES.items():
        for subject, (text, width, height) in TAKE_SUBJECTS.items():
            generate(f"{style}-{subject}", f"{text}, {look}", 4242, width, height, RAW / "takes")


def make(names):
    for name in names or PICTURES:
        name, _, other_seed = name.partition(":")     # name:seed tries a take, as RAW/name-seed.png
        seed, width, height, subject = PICTURES[name]
        init = upload(layout()) if name == "open-space" else None
        generate(f"{name}-{other_seed}" if other_seed else name, f"{subject}, {LOOK}",
                 int(other_seed or seed), width, height, RAW, init)


# The name, the width it ships at, its webp quality.
SHIP = {name: (256, 82) for name in ("maelle", "bastien", "ingrid", "nolan", "lou", "theo", "yasmine", "odile")}
SHIP |= {"cle": (1216, 80), "capture": (1000, 78), "forge": (1000, 78), "bureau": (1000, 78),
         "inspecteur": (1000, 78), "morve": (560, 80), "cave": (560, 80), "open-space": (1216, 86)}
# The lighter copy gobelin/index.html offers in its srcset, named name-width.webp: the home page
# shows these pictures far smaller than their full size (r58). Name, width, webp quality.
PORTRAITS = ("maelle", "bastien", "ingrid", "nolan", "lou", "theo", "yasmine", "odile")
SMALLER = {name: (168, 72) for name in PORTRAITS} | {"cle": (720, 72), "capture": (720, 72)}
BOLD = "/usr/share/fonts/liberation-sans-fonts/LiberationSans-Bold.ttf"
# What the whiteboard says: the same words as the alt text in a-propos.html and equipe.html.
BOARD_LINES = (("JALON BÊTA : VEN. 13/11", (176, 28, 62), 56),
               ("FORGE (serveur de build) :", (26, 42, 122), 44),
               ("forge.gobelin-hurlant.example", (26, 42, 122), 46),
               ("compte QA : qa", (26, 42, 122), 44),
               ("mdp : demander à Théo", (26, 42, 122), 44),
               ("2FA : après la bêta !!", (176, 28, 62), 44))


def marker(picture, text, x, y, colour, size, rng):
    """One line in marker pen: each letter a little off, so it was not typed."""
    from PIL import Image, ImageDraw, ImageFont
    font = ImageFont.truetype(BOLD, size)
    for letter in text:
        cell = Image.new("L", (size * 2, size * 2), 0)
        ImageDraw.Draw(cell).text((size // 2, size // 2), letter, font=font, fill=235)
        cell = cell.rotate(rng.uniform(-2.5, 2.5), resample=Image.BICUBIC)
        picture.paste(Image.new("RGB", cell.size, colour),
                      (int(x) - size // 2, int(y + rng.uniform(-1.5, 1.5)) - size // 2), cell)
        x += font.getlength(letter) + 0.5


def write_board(picture, box):
    """The clue, in letters that can be read, inside the painted whiteboard."""
    import random
    from PIL import ImageFilter
    left, top, right, bottom = box
    rng = random.Random(13)
    layer = picture.copy()
    gap = (bottom - top - sum(line[2] for line in BOARD_LINES)) / (len(BOARD_LINES) + 1)
    y = top + gap
    for text, colour, size in BOARD_LINES:
        marker(layer, text, left + 30, y, colour, size, rng)
        y += size + gap
    layer = layer.filter(ImageFilter.GaussianBlur(0.5))
    picture.paste(layer.crop(box), box)


def poster_title(picture):
    """The game's title on the key art, on a dark band that leaves the goblin alone."""
    from PIL import Image, ImageDraw, ImageFont
    width, height = picture.size
    band = Image.new("L", (1, height), 0)
    for y in range(height):
        band.putpixel((0, y), int(235 * max(0, (y - height * 0.68) / (height * 0.2))) if y < height * 0.88 else 235)
    picture.paste(Image.new("RGB", picture.size, (8, 10, 8)), (0, 0), band.resize(picture.size))
    draw = ImageDraw.Draw(picture)
    title = ImageFont.truetype(BOLD, 96)
    x = (width - draw.textlength("GROTTE FISCALE", font=title)) / 2
    draw.text((x, height - 168), "GROTTE FISCALE", font=title, fill=(182, 242, 60))
    line = ImageFont.truetype(BOLD, 38)
    draw.text(((width - draw.textlength("Le fisc arrive. Hurlez.", font=line)) / 2, height - 62),
              "Le fisc arrive. Hurlez.", font=line, fill=(242, 244, 239))


def ship():
    from PIL import Image
    for name, (width, quality) in SHIP.items():
        kept = RAW / f"{name}-{PICTURES[name][0]}.png"     # the take that won, when it was a take
        picture = Image.open(kept if kept.exists() else RAW / f"{name}.png").convert("RGB")
        if name == "open-space":
            write_board(picture, BOARD_INSIDE)
        if name == "cle":
            poster_title(picture)
        out = [(IMG / f"{name}.webp", width, quality)]
        if name in SMALLER:
            small, small_quality = SMALLER[name]
            out.append((IMG / f"{name}-{small}.webp", small, small_quality))
        for target, size, q in out:
            height = round(picture.height * size / picture.width)
            picture.resize((size, height), Image.LANCZOS).save(target, quality=q, method=6)
            print(f"{target.name}: {size}x{height}, {target.stat().st_size // 1024} KB")


def main():
    action = sys.argv[1] if len(sys.argv) > 1 else ""
    if action == "takes":
        takes()
    elif action == "make":
        make(sys.argv[2:])
    elif action == "ship":
        ship()
    else:
        sys.exit(__doc__)


if __name__ == "__main__":
    main()
